p = Path(__file__).with_name('catalog.json')
c = json.loads(p.read_text(encoding='utf-8'))
ROWS.pop('nl'); ROWS.pop('bn')
for language, tag in {'ja':'ja-JP', 'fr':'fr-FR', 'de':'de-DE', 'pl':'pl-PL', 'ko':'ko-KR', 'it':'it-IT', 'vi':'vi-VN'}.items():
    ROWS[tag] = ROWS.pop(language)
