ROWS['fa'] = 'استخراج در پوشه|انتخاب همه|پاک کردن انتخاب|فایل‌های انتخاب‌شده با حفظ زیرپوشه‌ها در پوشه جدید Birlevo قرار می‌گیرند. فایل‌های موجود حفظ می‌شوند. این صفحه را باز نگه دارید. هنگام لغو یا خطا، اگر ارائه‌دهنده اجازه دهد پوشه جدید حذف می‌شود؛ وقفه ممکن است فایل‌های ناقص باقی بگذارد.|%1$d فایل در پوشه جدید استخراج شد.|ممکن است فایل‌هایی در پوشه جدید باقی بمانند. پیش از تلاش دوباره بررسی کنید:'
assert set(ROWS) == set(c['locales'])
for key in KEYS:
    if key not in c['keys']:
        c['keys'].append(key)
        for values in c['locales'].values(): values.append('')
for locale, row in ROWS.items():
    values = row.split('|'); assert len(values) == len(KEYS)
    for key, value in zip(KEYS, values): c['locales'][locale][c['keys'].index(key)] = value
p.write_text(json.dumps(c, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
